examples.command:
mount -F nfs {{HOST}}:{{EXPORT_PATH}} {{MOUNT_POINT}}
lofiadm -a {{ISO_FILE}}
mount -F hsfs -o ro /dev/lofi/1 {{MOUNT_POINT}}

mkfs.xfs {{DEVICE}}
mkdir -p {{MOUNT_POINT}}
echo "UUID=$(blkid -s UUID -o value {{DEVICE}}) {{MOUNT_POINT}} xfs defaults,nofail 0 0" >> /etc/fstab
systemctl daemon-reload
mount -a
df -hT {{MOUNT_POINT}}

lvcreate -n {{LV}} -l 100%FREE {{VG}}
mkfs.xfs /dev/{{VG}}/{{LV}}
mkdir -p {{MOUNT_POINT}}
echo '/dev/mapper/{{VG}}-{{LV}} {{MOUNT_POINT}} xfs defaults 0 0' >> /etc/fstab
systemctl daemon-reload
mount -a
